const fs = require('fs');
const PizZip = require('pizzip');
const Docxtemplater = require('docxtemplater');

const templatePath = 'C:\\Users\\siddharth.chandran\\Downloads\\node-v24.20.0-win-x64\\node-v24.20.0-win-x64\\templates\\RC_TEMPLATE_TAGGED.docx';
const content = fs.readFileSync(templatePath, 'binary');
const zip = new PizZip(content);
const doc = new Docxtemplater(zip, { paragraphLoop: true, linebreaks: true });

doc.render(items[0].json.rc);

const buf = doc.getZip().generate({ type: 'nodebuffer' });

const reportCode = $('On Form Submit').item.json['Report Code'] || 'RXXX';
const reportName = items[0].json.rc.report_name || items[0].json.rc.ticket_id;
const rcFileName = `${reportCode}-${reportName}-Release Certificate.docx`;

return [{
  json: { fileName: rcFileName },
  binary: {
    rc_file: {
      data: buf.toString('base64'),
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      fileName: rcFileName
    }
  }
}];

const fs2 = require('fs');
const PizZip2 = require('pizzip');
const Docxtemplater2 = require('docxtemplater');

const tcTemplatePath = 'C:\\Users\\siddharth.chandran\\Downloads\\node-v24.20.0-win-x64\\node-v24.20.0-win-x64\\templates\\TC_CUBEVIEW_TEMPLATE_TAGGED.docx';
const tcContent = fs2.readFileSync(tcTemplatePath, 'binary');
const tcZip = new PizZip2(tcContent);
const tcDoc = new Docxtemplater2(tcZip, { paragraphLoop: true, linebreaks: true });

tcDoc.render(items[0].json.tc_cube_view);

const tcBuf = tcDoc.getZip().generate({ type: 'nodebuffer' });

const reportCode2 = $('On Form Submit').item.json['Report Code'] || 'RXXX';
const reportName2 = items[0].json.rc.report_name || items[0].json.tc_cube_view.modules[0].module_name;
const tcFileName = `${reportCode2}-${reportName2}-Testcase Document.docx`;

return [{
  json: {},
  binary: {
    tc_file: {
      data: tcBuf.toString('base64'),
      mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      fileName: tcFileName
    }
  }
}];

// ============================================================
// PASTE THIS INTO THE PARSER NODE (the one between Basic LLM
// Chain and the two docx-generator Code nodes)
// ============================================================

const raw = items[0].json.text
  || items[0].json.output
  || items[0].json.response
  || items[0].json.data
  || JSON.stringify(items[0].json);

const cleaned = raw.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Could not parse LLM output as JSON. Raw text was: ' + raw.slice(0, 500));
}

// ---- Today's real date (the AI cannot reliably know this, so never trust it) ----
const today = new Date();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');
const yyyy = today.getFullYear();
const todayStr = `${mm}/${dd}/${yyyy}`;

if (parsed.rc) {
  parsed.rc.reviewed_by = 'Lakshmi Akili';
  parsed.rc.review_reviewed_by = 'Lakshmi Akili';

  // Version is the TEMPLATE's own version number, not the release's -
  // it's always this fixed value, confirmed identical across every real example
  parsed.rc.version = '0.2.2';

  if (!parsed.rc.build || parsed.rc.build.toUpperCase() === 'N/A') {
    parsed.rc.build = '--';
  }

  parsed.rc.date = todayStr;
  parsed.rc.build_date = todayStr;
  parsed.rc.build_no = parsed.rc.build_no || '0.1';
  parsed.rc.build_remarks = parsed.rc.build_remarks || 'Completed';
  parsed.rc.defects_identified = parsed.rc.defects_identified || 0;
  parsed.rc.bugs_fixed = parsed.rc.bugs_fixed || 0;

  // Certified By / Developer Name now comes from the form, not the AI -
  // this guarantees accuracy and that both fields always match
  const certifier = $('On Form Submit').item.json['Certified By'] || parsed.rc.certified_by || 'N/A';
  parsed.rc.certified_by = certifier;
  parsed.rc.developer_name = certifier;

  // Ticket Number now comes from the form too, not AI extraction
  parsed.rc.ticket_id = $('On Form Submit').item.json['Ticket Number'] || parsed.rc.ticket_id || 'N/A';

  const env = (parsed.rc.environment || 'QA').toUpperCase();
  parsed.rc.env_is_dev = env === 'DEV';
  parsed.rc.env_is_qa = env === 'QA';
  parsed.rc.env_is_prod = env === 'PROD';

  // review_module and checkin_modules both mirror the environment -
  // previously missing, which is why "undefined" appeared in the doc
  parsed.rc.review_module = env;
  parsed.rc.checkin_modules = env;

  const status = (parsed.rc.status || 'Approved').toLowerCase();
  parsed.rc.status_is_approved = status === 'approved';
  parsed.rc.status_is_rejected = status === 'rejected';
  parsed.rc.status_is_conditional = status.includes('conditional');

  const testing = (parsed.rc.testing_type || 'Smoke').toLowerCase();
  parsed.rc.testing_is_smoke = testing === 'smoke';
  parsed.rc.testing_is_bat = testing === 'bat';
  parsed.rc.testing_is_regression = testing === 'regression';
  parsed.rc.testing_is_hotfix = testing === 'hotfix';

  // ---- Compute REAL test case counts from the actual generated checklist ----
  let executed = 0, passed = 0, failed = 0;
  if (parsed.tc_cube_view && Array.isArray(parsed.tc_cube_view.modules)) {
    for (const mod of parsed.tc_cube_view.modules) {
      if (!Array.isArray(mod.checklist)) continue;
      for (const item of mod.checklist) {
        executed++;
        if (item.yes_mark === '\u2611') passed++;
        else if (item.no_mark === '\u2611') failed++;
      }
    }
  }
  parsed.rc.tc_executed = executed;
  parsed.rc.tc_passed = passed;
  parsed.rc.tc_failed = failed;
  parsed.rc.review_tc_count = executed;
}

if (parsed.tc_cube_view) {
  parsed.tc_cube_view.review_date = todayStr;
  parsed.tc_cube_view.reviewer_name = $('On Form Submit').item.json['Certified By'] || parsed.tc_cube_view.reviewer_name || 'N/A';

  // Build the remediation filename properly: <ReportName>_Remediation_MM-DD-YYYY.xlsx
  const dashDate = todayStr.replace(/\//g, '-');
  const rName = (parsed.rc && parsed.rc.report_name) || 'Report';
  parsed.tc_cube_view.remediation_file_name = `${rName}_Remediation_${dashDate}.xlsx`;

  // Testcase Summary table label adapts to ticket type
  const typeLabels = { BOOK: 'Total Books', PARAMETER_CHANGE: 'Total Parameters', CUBE_VIEW: 'Total Reports' };
  parsed.tc_cube_view.total_label = typeLabels[parsed.ticket_type] || 'Total Reports';

  // ---- Testcase Summary table numbers ----
  const modCount = Array.isArray(parsed.tc_cube_view.modules) ? parsed.tc_cube_view.modules.length : 0;
  const perReport = modCount > 0 ? (parsed.tc_cube_view.modules[0].checklist || []).length : 0;
  parsed.tc_cube_view.total_reports = modCount;
  parsed.tc_cube_view.tc_per_report = perReport;
  parsed.tc_cube_view.total_testcase = modCount * perReport;
}

return [{ json: parsed }];

const PizZip = require('pizzip');

const rcFile = items[0].binary.rc_file;
const tcFile = items[0].binary.tc_file;

if (!rcFile || !tcFile) {
  throw new Error('Missing rc_file or tc_file - check the Merge node is set to Combine / Merge By Position, and that both Code nodes use those exact binary property names.');
}

const zip = new PizZip();
zip.file(rcFile.fileName, Buffer.from(rcFile.data, 'base64'));
zip.file(tcFile.fileName, Buffer.from(tcFile.data, 'base64'));

const zipBuf = zip.generate({ type: 'nodebuffer' });

const reportCode = $('On Form Submit').item.json['Report Code'] || 'RXXX';
const ticketNumber = $('On Form Submit').item.json['Ticket Number'] || 'NoTicket';
const zipFileName = `${reportCode}-${ticketNumber}.zip`;

return [{
  json: {},
  binary: {
    data: {
      data: zipBuf.toString('base64'),
      mimeType: 'application/zip',
      fileName: zipFileName
    }
  }
}];
